    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 20px;
}
.eon8-live-page .industry-card {
    background: #fff;
    padding: 25px 15px;
    border-radius: 14px;
    transition: 0.4s ease;
    border: 1px solid #044db5;
}
.eon8-live-page .industry-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 15px 35px #044db5;
}
.eon8-live-page .industry-icon {
    width: 45px;
    height: 45px;
    margin: 0 auto 12px;
    color: #044db5 ;
}
.eon8-live-page .industry-icon svg {
    width: 100%;
    height: 100%;
}
.eon8-live-page .industry-card h3 {
    font-size: 16px;
    color: #111;
}
.eon8-live-page .industries-footer {
    margin-top: 40px;
    font-size: 15px;
    color: #444;
    max-width: 750px;
    margin-left: auto;
    margin-right: auto;
}
.eon8-live-page .linkedin-section-white {
  padding: 0px 20px;
  background: #ffffff;
  color: #0f172a;
}
.eon8-live-page .linkedin-section-white .container {
  max-width: 1150px;
  margin: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 50px;
}
.eon8-live-page .linkedin-left-white {
  flex: 1;
}
.eon8-live-page .linkedin-left-white h2 {
  font-size: 2.4rem;
  line-height: 1.3;
  margin-bottom: 18px;
  color: #0f172a;
  font-weight: 700;
}
.eon8-live-page .linkedin-left-white span {
  color: #044db5;
}
.eon8-live-page .desc-white {
  color: #475569;
  margin-bottom: 24px;
  line-height: 1.8;
  font-size: 1.02rem;
}
.eon8-live-page .points-white {
  list-style: none;
  padding: 0;
  margin: 0;
}
.eon8-live-page .points-white li {
  margin-bottom: 14px;
  color: #0f172a;
  font-size: 1rem;
  position: relative;
  padding-left: 30px;
  font-weight: 500;
}
.eon8-live-page .points-white li::before {
  content: "✔";
  position: absolute;
  left: 0;
  top: 0;
  color: #044db5;
  font-weight: bold;
}
.eon8-live-page .india-white {
  margin-top: 25px;
  color: #64748b;
  font-size: 0.95rem;
}
.eon8-live-page .linkedin-right-white {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.eon8-live-page .card-white {
  padding: 24px;
  border-radius: 18px;
  background: #ffffff;
  border: 1px solid #dbeafe;
  box-shadow: 0 10px 30px rgba(4, 77, 181, 0.08);
  transition: 0.35s ease;
}
.eon8-live-page .card-white:hover {
  transform: translateY(-6px);
  border-color: #044db5;
  box-shadow: 0 18px 40px rgba(4, 77, 181, 0.15);
}
.eon8-live-page .card-white h3 {
  color: #044db5;
  margin-bottom: 10px;
  font-size: 1.1rem;
}
.eon8-live-page .card-white p {
  color: #475569;
  line-height: 1.6;
  margin: 0;
}
@media (max-width: 900px) {.eon8-live-page .linkedin-section-white .container {
    flex-direction: column;
    text-align: center;
  }
.eon8-live-page .linkedin-left-white h2 {
    font-size: 2rem;
  }
.eon8-live-page .points-white li {
    text-align: left;
  }
.eon8-live-page .linkedin-right-white {
    grid-template-columns: 1fr;
    width: 100%;
  }}
.eon8-live-page .why-eon8-white {
  padding: 0px 20px;
  background: #ffffff;
}
.eon8-live-page .why-eon8-white .container {
  max-width: 1100px;
  margin: auto;
}
.eon8-live-page .head-white {
  text-align: center;
  margin-bottom: 55px;
}
.eon8-live-page .head-white h2 {
  font-size: 2.4rem;
  color: #0f172a;
  line-height: 1.3;
  margin-bottom: 12px;
}
.eon8-live-page .head-white span {
  color: #044db5;
}
.eon8-live-page .head-white p {
  color: #64748b;
  font-size: 1rem;
}
.eon8-live-page .stack-white {
  display: flex;
  flex-direction: column;
  gap: 22px;
}
.eon8-live-page .block-white {
  display: flex;
  align-items: stretch;
  background: #ffffff;
  border-radius: 18px;
  overflow: hidden;
  transition: 0.35s ease;
  border: 1px solid #dbeafe;
  box-shadow: 0 10px 30px rgba(4, 77, 181, 0.06);
}
.eon8-live-page .bar-white {
  width: 6px;
  background: linear-gradient(to bottom, #044db5, #3b82f6);
  transition: 0.35s ease;
}
.eon8-live-page .content-white {
  padding: 24px;
  width: 100%;
}
.eon8-live-page .content-white h3 {
  margin-bottom: 12px;
  font-size: 1.15rem;
  color: #044db5;
  font-weight: 700;
}
.eon8-live-page .content-white p {
  color: #475569;
  font-size: 0.96rem;
  line-height: 1.7;
  margin: 0;
}
.eon8-live-page .tags-white {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.eon8-live-page .tags-white span {
  background: #eff6ff;
  color: #044db5;
  padding: 8px 14px;
  border-radius: 10px;
  font-size: 0.85rem;
  font-weight: 600;
  border: 1px solid #bfdbfe;
  transition: 0.3s ease;
}
.eon8-live-page .tags-white span:hover {
  background: #044db5;
  color: #ffffff;
}
.eon8-live-page .block-white:hover {
  transform: translateX(8px);
  border-color: #044db5;
  box-shadow: 0 18px 45px rgba(4, 77, 181, 0.12);
}
.eon8-live-page .block-white:hover .bar-white {
  width: 10px;
}
@media (max-width: 768px) {.eon8-live-page .why-eon8-white {
    padding: 60px 18px;
  }
.eon8-live-page .head-white h2 {
    font-size: 1.9rem;
  }
.eon8-live-page .content-white {
    padding: 20px;
  }
.eon8-live-page .tags-white span {
    font-size: 0.8rem;
    padding: 7px 12px;
  }}
.eon8-live-page .ld-campaign-section {
    padding: 0px 20px;
    text-align: center;
}
.eon8-live-page .ld-title {
    font-size: 34px;
    font-weight: 700;
    margin-bottom: 50px;
    color: #222;
}
.eon8-live-page .ld-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 25px;
}
.eon8-live-page .ld-card {
    background: #ffffff;
    padding: 30px 25px;
    border-radius: 16px;
    transition: all 0.4s ease;
    box-shadow: 0 10px 25px rgba(0,0,0,0.05);
    border-top: 4px solid #044db5;
}
.eon8-live-page .ld-card:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 40px #044db5;
}
.eon8-live-page .ld-icon {
    width: 50px;
    height: 50px;
    margin: 0 auto 15px;
    color: #ff6a00;
}
.eon8-live-page .ld-icon svg {
    width: 100%;
    height: 100%;
    color: #044db5;
}
.eon8-live-page .ld-card h3 {
    font-size: 18px;
    margin-bottom: 10px;
    color: #111;
}
.eon8-live-page .ld-card p {
    font-size: 14px;
    color: #555;
    line-height: 1.6;
}
.eon8-live-page .faq-linkedin {
    padding: 20px 20px;
    background: #ffffff;
    font-family: Arial, sans-serif;
    padding-bottom: 30px;
}
.eon8-live-page .container {
    max-width: 900px;
    margin: auto;
}
.eon8-live-page .faq-header {
    text-align: center;
    margin-bottom: 40px;
}
.eon8-live-page .faq-header h2 {
    font-size: 32px;
    color: #222;
}
.eon8-live-page .faq-item {
    border-bottom: 1px solid #eee;
}
.eon8-live-page .faq-question {
    width: 100%;
    background: none;
    border: none;
    text-align: left;
    padding: 18px;
    font-size: 16px;
    font-weight: 600;
    color: #333;
    display: flex;
    justify-content: space-between;
    cursor: pointer;
    transition: 0.3s;
}
.eon8-live-page .faq-question:hover {
    color: #393979;
}
.eon8-live-page .faq-answer {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s ease;
    padding: 0 18px;
}
.eon8-live-page .faq-answer p {
    padding: 10px 0;
    color: #555;
    font-size: 14px;
}
.eon8-live-page .faq-item.active .faq-answer {
    max-height: 200px;
}
.eon8-live-page .faq-item.active span {
    transform: rotate(45deg);
}
.eon8-live-page .faq-question span {
    font-size: 20px;
    color: #393979;
    transition: 0.3s;
}
@media(max-width: 600px) {.eon8-live-page .faq-header h2 {
        font-size: 24px;
    }}
.eon8-live-page .btn-eat24 {
    background: linear-gradient(90deg , #f58322, #ff9c47);
    box-shadow: none !important;
    padding: 15px 20px;
    border-radius: 4px;
    text-transform: uppercase;
    font-weight: 600;
    color: #f9f9f9;
    margin-right: 15px;
}
